import java.util.*;

public class Main {
    static List<Integer> fallingSquares(int[][] positions) {
        List<int[]> dropped = new ArrayList<>();        // list of {left, right, height}
        List<Integer> result = new ArrayList<>();
        int overallMax = 0;
        for (int[] p : positions) {
            int left = p[0], side = p[1], right = left + side;
            int base = 0;
            for (int[] sq : dropped) {                        // check overlap against every previous square
                if (sq[0] < right && left < sq[1]) base = Math.max(base, sq[2]);
            }
            int newHeight = base + side;
            dropped.add(new int[]{left, right, newHeight});
            overallMax = Math.max(overallMax, newHeight);
            result.add(overallMax);
        }
        return result;
    }
}

