#include <bits/stdc++.h>
using namespace std;

vector<int> fallingSquares(vector<vector<int>>& positions) {
    vector<array<int,3>> dropped;               // list of {left, right, height}
    vector<int> result;
    int overallMax = 0;
    for (auto& p : positions) {
        int left = p[0], side = p[1], right = left + side;
        int base = 0;
        for (auto& sq : dropped) {                     // check overlap against every previous square directly
            if (sq[0] < right && left < sq[1]) base = max(base, sq[2]);
        }
        int newHeight = base + side;
        dropped.push_back({left, right, newHeight});
        overallMax = max(overallMax, newHeight);
        result.push_back(overallMax);
    }
    return result;
}
